import { test, expect } from '@playwright/test';

test.describe('Authentication Error Message', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display error message for incorrect password', async ({ page }) => {
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('wrongpassword');
    await page.getByRole('button', { name: 'Login' }).click();

    const errorMessage = await page.getByText('Incorrect password. Please try again.');
    await expect(errorMessage).toBeVisible();
  });

  test('should not display error message for correct password', async ({ page }) => {
    await page.getByLabel('Email').fill('user@example.com');
    await page.getByLabel('Password').fill('correctpassword');
    await page.getByRole('button', { name: 'Login' }).click();

    const errorMessage = page.getByText('Incorrect password. Please try again.');
    await expect(errorMessage).not.toBeVisible();
  });
});
